sys_script_client.script:
function onLoad() {

if (!r1Speed || !r2Speed ) {
    // Retrieve field values
    var trackLength = g_form.getValue('track_length') || 185; // Default to 185 if not set
    var r1Time = g_form.getValue('r1_time');
    var r2Time = g_form.getValue('r2_time');

    // Define constants
    const SCALE_FACTOR = 64;  // Scale factor for 1:64 scale
    const SECONDS_PER_HOUR = 3600;
    const INCHES_PER_MILE = 63360;

    // Initialize variables for calculated speeds
    var r1Speed = null;
    var r2Speed = null;

    // Calculate speed for R1 if r1_time exists
    if (r1Time) {
        r1Speed = (trackLength / r1Time) * (SECONDS_PER_HOUR / INCHES_PER_MILE) * SCALE_FACTOR;
        g_form.setValue('r1sSpeed',"R1 Speed " + (r1Speed ? r1Speed.toFixed(2) : "N/A") + " mph, "
    }

    // Calculate speed for R2 if r2_time exists
    if (r2Time) {
        r2Speed = (trackLength / r2Time) * (SECONDS_PER_HOUR / INCHES_PER_MILE) * SCALE_FACTOR;
        g_form.setValue('r2Speed',(r2Speed ? r2Speed.toFixed(2) : "N/A") + " mph";
    }

    // Concatenate the speed values into a display field, e.g., Speed_Display
    var speedDisplay = "R1 Speed (1:1): " + (r1Speed ? r1Speed.toFixed(2) : "N/A") + " mph, " +
                       "R2 Speed (1:1): " + (r2Speed ? r2Speed.toFixed(2) : "N/A") + " mph";
    g_form.setValue('title', speedDisplay); // Update display field
}
